-- LemmaYard problem catalog for Supabase, part 5 of 6 (SQL Editor -> New query -> paste -> Run).
-- Generated by `pnpm problems:export-sql` from problems/*; do not edit by hand.
-- The same catalog in one file is docs/supabase/problems.sql; the parts exist for SQL
-- editors that refuse a large paste. Run all 6 parts, in any order, after
-- docs/supabase/schema.sql (or `pnpm db:migrate`). Each part is its own transaction
-- over 9 problems, 12 tags and 1741 test cases (catalog: 50 problems,
-- 6625 test cases). It writes the same rows as `pnpm problems:import`: upsert by
-- slug (published), tags, and a full replacement of each problem's tags and test cases.
-- Safe to run again; it never unpublishes problems that are not listed here.
-- NOTE: this file contains the HIDDEN test cases too (is_sample = false). They are
-- public anyway, because problems/*/tests.json is committed to this repository.

BEGIN;

-- Refuse to run if another problem in the database already uses one of these numbers.
DO $$
DECLARE taken text;
BEGIN
  SELECT string_agg("slug" || ' (' || "number" || ')', ', ') INTO taken
  FROM "problems"
  WHERE "number" IN (44, 7, 25, 21, 40, 43, 35, 24, 48)
    AND "slug" NOT IN ($ly$rating-upsets$ly$, $ly$reverse-string$ly$, $ly$reversed-twins$ly$, $ly$sensor-spikes$ly$, $ly$shortest-full-playlist$ly$, $ly$smallest-task-order$ly$, $ly$spaced-harvest$ly$, $ly$squeeze-repeats$ly$, $ly$toll-free-passes$ly$);
  IF taken IS NOT NULL THEN
    RAISE EXCEPTION 'problem numbers already used by other problems in the database: %', taken;
  END IF;
END $$;

-- Park the numbers of existing rows so renumbering between them cannot collide;
-- every parked row gets its real number back from the upserts below.
UPDATE "problems" SET "number" = "number" + 1000000000
WHERE "slug" IN ($ly$rating-upsets$ly$, $ly$reverse-string$ly$, $ly$reversed-twins$ly$, $ly$sensor-spikes$ly$, $ly$shortest-full-playlist$ly$, $ly$smallest-task-order$ly$, $ly$spaced-harvest$ly$, $ly$squeeze-repeats$ly$, $ly$toll-free-passes$ly$);

INSERT INTO "tags" ("slug", "name") VALUES
  ($ly$array$ly$, $ly$Array$ly$),
  ($ly$sorting$ly$, $ly$Sorting$ly$),
  ($ly$binary-search$ly$, $ly$Binary Search$ly$),
  ($ly$string$ly$, $ly$String$ly$),
  ($ly$two-pointers$ly$, $ly$Two Pointers$ly$),
  ($ly$hash-table$ly$, $ly$Hash Table$ly$),
  ($ly$sliding-window$ly$, $ly$Sliding Window$ly$),
  ($ly$graph$ly$, $ly$Graph$ly$),
  ($ly$topological-sort$ly$, $ly$Topological Sort$ly$),
  ($ly$heap$ly$, $ly$Heap$ly$),
  ($ly$dynamic-programming$ly$, $ly$Dynamic Programming$ly$),
  ($ly$shortest-path$ly$, $ly$Shortest Path$ly$)
ON CONFLICT ("slug") DO NOTHING;

-- ---- rating-upsets ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (44, $ly$rating-upsets$ly$, $ly$Rating Upsets$ly$, $ly$hard$ly$, $ly$A chess club lists its members in the order they joined, together with their
current ratings: `ratings[i]` belongs to the member who joined `i`-th. The
club secretary calls two members an **upset pair** when the member who joined
earlier is rated more than `gap` points above the member who joined later,
that is, positions `i < j` with

`ratings[i] - ratings[j] > gap`.

Return the number of upset pairs.

## Constraints

- `0 <= ratings.length <= 10^5`
- `0 <= ratings[i] <= 10^9`
- `-10^9 <= gap <= 10^9`

## Notes

- `gap` can be negative: with `gap = -1` every pair with
  `ratings[i] >= ratings[j]` counts.
- Checking every pair takes quadratic time. For each member, count the
  matching members on one side with a sorted view of the values seen so far.
$ly$, $ly${"name":"countUpsets","params":[{"name":"ratings","type":"int[]"},{"name":"gap","type":"int"}],"returns":"int"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1900)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$rating-upsets$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$rating-upsets$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$array$ly$, $ly$sorting$ly$, $ly$binary-search$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$rating-upsets$ly$);
